/** Classes for the parts of a Field. React, Solid and plain HTML all use these. */
export const fieldParts = {
	root: "grid gap-1.5",
	label: "text-[13px]/5 font-[510] tracking-[-0.15px] text-foreground",
	/** The hint, or the error: set `data-invalid` on it to turn it red. */
	message: "text-xs/4 tracking-[-0.15px] text-(--subtle-foreground) data-invalid:text-destructive",
};

"use client";

import { type ReactNode, useId } from "react";
import { FieldContext } from "./field-context";
import { cn } from "@/lib/utils";
import { fieldParts } from "./field.styles";

export type FieldProps = {
	label: ReactNode;
	/** Helper text under the control. */
	hint?: ReactNode;
	/** Replaces the hint, marks the control invalid and is announced when it appears. */
	error?: ReactNode;
	className?: string;
	/** One control, such as an Input. It receives the id, the description and the invalid state. */
	children: ReactNode;
};

/** A label, a control and an optional hint or error, linked for assistive technology. */
export function Field({ label, hint, error, className, children }: FieldProps) {
	const id = useId();
	const message = error ?? hint;
	const { root, label: labelClass, message: messageClass } = fieldParts;

	return (
		<FieldContext
			value={{ id, describedBy: message ? `${id}-message` : undefined, invalid: !!error }}
		>
			<div className={cn(root, className)}>
				<label id={`${id}-label`} htmlFor={id} className={labelClass}>
					{label}
				</label>
				{children}
				{message && (
					<p
						id={`${id}-message`}
						aria-live="polite"
						data-invalid={error ? "" : undefined}
						className={messageClass}
					>
						{message}
					</p>
				)}
			</div>
		</FieldContext>
	);
}
